16	/// Meaningful HTML text is defined to be text that has either non-whitespace
17	/// characters, or does not contain a newline. Whitespace is defined as ASCII
18	/// whitespace.
19	///
20	/// ```
21	/// use biome_html_formatter::utils::children::is_meaningful_html_text;
22	///
23	/// assert_eq!(is_meaningful_html_text("     \t\r   "), true);
24	/// assert_eq!(is_meaningful_html_text("     \n\r   "), false);
25	/// assert_eq!(is_meaningful_html_text("  Alien   "), true);
26	/// assert_eq!(is_meaningful_html_text("\n  Alien   "), true);
27	/// assert_eq!(is_meaningful_html_text("  Alien   \n"), true);
28	/// assert_eq!(is_meaningful_html_text(""), true);
29	/// ```
30	pub fn is_meaningful_html_text(text: &str) -> bool {
31	    let mut has_newline = false;
32	    for byte in text.bytes() {
33	        // If there is a non-whitespace character
34	        if !HTML_WHITESPACE_CHARS.contains(&byte) {
35	            return true;
36	        } else if byte == b'\n' {
37	            has_newline = true;
38	        }
39	    }
40	
41	    !has_newline
42	}
